export default {
  data() {
    return {
      orderId: null,
      order: null,
      reviewForm: {
        orderId: null,
        idleId: null,
        rating: 5,
        content: ''
      },
      rules: {
        content: [
          { required: true, message: '请填写评价内容', trigger: 'blur' },
          { min: 5, max: 500, message: '长度在 5 到 500 个字符', trigger: 'blur' }
        ]
      },
      loading: false
    };
  },
  created() {
    this.orderId = this.$route.query.orderId;
    if (this.orderId) {
      this.getOrderInfo();
      this.checkReviewExists();
    } else {
      this.$message.error('订单ID不存在');
      this.goBack();
    }
  },
  methods: {
    // 获取订单信息
    getOrderInfo() {
      this.loading = true;
      this.$api.getOrder({
        id: this.orderId
      }).then(res => {
        if (res.status_code === 1) {
          this.order = res.data;
          this.reviewForm.orderId = this.orderId;
          // 保存商品ID以便评价使用
          this.reviewForm.idleId = this.order.idleId;
        } else {
          this.$message.error(res.msg || '获取订单信息失败');
          this.goBack();
        }
      }).catch(err => {
        console.error('获取订单信息失败', err);
        this.$message.error('订单获取失败');
      }).finally(() => {
        this.loading = false;
      });
    },
    
    // 检查是否已经评价过
    checkReviewExists() {
      this.$api.getIdleReviews({
        orderId: this.orderId
      }).then(res => {
        if (res.status_code === 1 && res.data && res.data.length > 0) {
          this.$message.warning('您已经评价过该订单');
          this.$router.push({ path: '/orders' });
        }
      }).catch(err => {
        console.error('检查评价失败', err);
      });
    },
    
    // 提交评价
    submitReview() {
      this.$refs.reviewForm.validate(valid => {
        if (valid) {
          this.loading = true;
          this.$api.addReview(this.reviewForm)
            .then(res => {
              if (res.status_code === 1) {
                this.$message.success('评价成功');
                this.$router.push({ path: '/me' });
              } else {
                this.$message.error(res.msg || '评价失败');
              }
            })
            .catch(err => {
              console.error('评价失败', err);
              this.$message.error('评价失败，请重试');
            })
            .finally(() => {
              this.loading = false;
            });
        }
      });
    },
    
    // 返回订单列表
    goBack() {
      this.$router.push({ path: '/me' });
    },
    
    // 格式化时间
    formatTime(time) {
      if (!time) return '无';
      return new Date(time).toLocaleString();
    }
  }
};
